{
  "technical_and_design_decisions": [
    "All new functions will be implemented in Go, following the existing code patterns in the Hyperledger Fabric configtx package.",
    "We will reuse the existing ConfigUpdate building and signing mechanisms, extending them as needed.",
    "For the CLI tool, we will use a command-line argument parser (e.g., cobra) and support JSON input files for batch operations.",
    "We will maintain backward compatibility by keeping the existing GetConfiguration/SetConfiguration methods while adding the new individual setter functions.",
    "New setter functions will persist existing values for fields not being modified, as specified.",
    "Consenter add/remove functions will match all four fields (host, port, client TLS cert, server TLS cert) for safety.",
    "The RemoveLegacyOrdererAddresses and RemoveKafkaBrokers functions will raise errors if users attempt to set those fields directly."
  ],
  "assumptions": [
    "The development environment is already set up with the existing Fabric codebase and all dependencies.",
    "The developer has full understanding of the existing configtx library and its API structure.",
    "Unit tests are required for all new functions, and integration tests will be minimal but cover critical workflows.",
    "All example updates will be done in the same codebase (e.g., in /examples directory of the fabric-config repo).",
    "The CLI tool will use an existing Fabric connection profile format and will connect to peers for config block retrieval and orderer for submission.",
    "No new external libraries are needed beyond those already used in the project.",
    "The developer will perform self-review and debugging; no separate QA team is assumed."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Project Setup and Design Review",
      "activity_description": "Review user stories, design overall approach, ensure understanding of existing code, update local environment.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Add Consortium Function",
      "activity_description": "Implement function to add a new consortium to the consortiums group, handle edge cases (no orgs), update example code to demonstrate adding consortium + orgs.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 - Unsigned ConfigUpdateEnvelope",
      "activity_description": "Implement function to return a cb.ConfigUpdateEnvelope without requiring signing identities, allowing later signing via peer channel commands.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "U3 - Remove Legacy Orderer Addresses",
      "activity_description": "Implement RemoveLegacyOrdererAddresses function to remove top-level orderer addresses, ensure new genesis blocks omit the field, prevent updates to OrdererAddresses.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A5",
      "activity_name": "U4 - Remove Kafka Brokers",
      "activity_description": "Implement function to remove KafkaBrokers section from config, update examples to show Kafka to EtcdRaft migration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "U5 - Add/Remove Consenters",
      "activity_description": "Implement AddConsenter and RemoveConsenter functions for etcdraft orderer configuration, matching host, port, and both certs for removal.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "U7 - Orderer Individual Setters",
      "activity_description": "Implement setter functions for OrdererGroup: SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetKafkaBrokers/SetEtcdRaftMetadata, SetConsensusState, and additional EtcdRaft metadata setters. Update examples.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "U8 - MSP Individual Setters",
      "activity_description": "Implement MSP setter functions for OrdererOrgGroup, ApplicationOrgGroup, and ConsortiumOrgGroup: AddRootCert/RemoveRootCert, AddIntermediateCert/RemoveIntermediateCert, AddAdminCert/RemoveAdminCert, AddCRL/RemoveCRL, AddOUIdentifier/RemoveOUIdentifier, SetCryptoConfig, AddTLSRootCert/RemoveTLSRootCert, AddTLSIntermediateCert/RemoveTLSIntermediateCert, SetClient/Peer/Admin/OrdererOUIdentifier, Enable/DisableNodeOUs. Update examples.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "U6 - CLI Tool Core Infrastructure",
      "activity_description": "Build CLI tool that parses batch update JSON, connection profile, signing identities, supports --dryrun flag, fetches config blocks via discovery service, submits config update transactions to orderer. Implement general framework and error handling.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A10",
      "activity_name": "U6 - CLI Tool Operations Implementation",
      "activity_description": "Implement specific operations: updateChannelMSP (admin cert replacement), add/remove/replace consenter, update TLS certs for consenters, add/remove anchor peers, with support for stacking multiple operations and dry-run output.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "Unit Testing",
      "activity_description": "Write comprehensive unit tests for all new functions (U1-U8, CLI tool components) using existing test framework, covering typical and edge cases.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A12",
      "activity_name": "Integration Testing",
      "activity_description": "Set up and execute integration tests for key flows: consortium addition, unsigned envelope, legacy address removal, consenter add/remove, CLI tool batch operations on simulated network.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A13",
      "activity_name": "Documentation and Examples Update",
      "activity_description": "Update existing documentation (README, API docs) and example code to reflect new functions and CLI tool usage.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A14",
      "activity_name": "Bug Fixing and Final Polish",
      "activity_description": "Address issues found during testing, perform code cleanup, final review, ensure all acceptance criteria are met.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 164
  }
}

